<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/bootstrap.php';
use Artdon\MaterialCenter\Adapters\LegacyAuthAdapter;use Artdon\MaterialCenter\Security\PermissionService;use Artdon\MaterialCenter\Services\AdaptationService;
header('Content-Type:application/json;charset=utf-8');header('Cache-Control:no-store');
try{$user=(new LegacyAuthAdapter())->current();$permission=new PermissionService();$service=new AdaptationService();if($_SERVER['REQUEST_METHOD']==='GET'&&($_GET['action']??'')==='approved'){$permission->require($user,'material_center.view');$data=$service->approved((int)($_GET['legacy_product_id']??0));echo json_encode(['ok'=>true,'data'=>$data],JSON_UNESCAPED_UNICODE);exit;}$permission->require($user,'material_center.adaptation.manage');if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf((string)($_POST['csrf_token']??'')))throw new RuntimeException('安全令牌已过期。',419);$action=(string)($_POST['action']??'sync');if($action==='sync')$data=$service->syncProducts($user->id);elseif($action==='save_group')$data=['id'=>$service->saveGroup($_POST,$user->id)];elseif($action==='save_option'){$d=$_POST;$d['conditions']=json_decode((string)($_POST['conditions_json']??'[]'),true)?:[];$data=['id'=>$service->saveOption($d,$user->id)];}elseif($action==='save_conflict')$data=['id'=>$service->saveConflict($_POST,$user->id)];elseif($action==='evaluate')$data=$service->evaluate((int)$_POST['product_id'],json_decode((string)($_POST['option_ids']??'[]'),true)?:[],json_decode((string)($_POST['context_json']??'{}'),true)?:[]);elseif($action==='approve'){$permission->require($user,'material_center.approve');$service->approveProduct((int)$_POST['product_id'],$user->id);$data=[];}else throw new RuntimeException('操作无效。');echo json_encode(['ok'=>true,'data'=>$data],JSON_UNESCAPED_UNICODE);}
catch(Throwable$e){http_response_code($e->getCode()>=400&&$e->getCode()<600?$e->getCode():422);echo json_encode(['ok'=>false,'message'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
